import{_ as o,a,b as n,c as r,d as l,e as s}from"./chunks/jfi_telemetry_config.CCdD35m_.js";import{_ as u,c,o as d,al as e,j as i}from"./chunks/framework.D8UyiDWg.js";const P=JSON.parse('{"title":"J.Fi Wireless Telemetry Module","description":"","frontmatter":{},"headers":[],"relativePath":"zh/telemetry/jfi_telemetry.md","filePath":"zh/telemetry/jfi_telemetry.md"}'),h={name:"zh/telemetry/jfi_telemetry.md"};function m(g,t,p,f,b,_){return d(),c("div",null,t[0]||(t[0]=[e('<h1 id="j-fi-wireless-telemetry-module" tabindex="-1">J.Fi Wireless Telemetry Module <a class="header-anchor" href="#j-fi-wireless-telemetry-module" aria-label="Permalink to &quot;J.Fi Wireless Telemetry Module&quot;">​</a></h1><p>The J.MARPLE <a href="https://jmarple.ai/j-fi/" target="_blank" rel="noreferrer">J.Fi telemetry module</a> is a compact and lightweight wireless communication device featuring a PCB-integrated antenna or external antenna, enabling seamless telemetry connections between various drone flight controllers (FC) and ground control stations.</p><p>This module includes a Pixhawk-standard JST 6-pin <code>TELEM</code> connector, ensuring compatibility with all PX4-based flight controllers. It supports quick plug-and-play operation to <code>TELEM1</code> with default settings, requiring no additional configuration.</p><p>The J.Fi telemetry module provides reliable communication up to approximately 500 meters when using a PCB-integrated antenna. Operating in the 2.4GHz frequency band, it allows unrestricted global use without regulatory limitations.</p><p><img src="'+o+'" alt="J.Fi Wireless Telemetry Module"></p><h2 id="购买渠道" tabindex="-1">购买渠道 <a class="header-anchor" href="#购买渠道" aria-label="Permalink to &quot;购买渠道&quot;">​</a></h2><ul><li><a href="https://jmarple.ai/j-fi/" target="_blank" rel="noreferrer">https://jmarple.ai/j-fi/</a></li></ul><h2 id="technical-specifications" tabindex="-1">Technical Specifications <a class="header-anchor" href="#technical-specifications" aria-label="Permalink to &quot;Technical Specifications&quot;">​</a></h2><h3 id="wireless-performance" tabindex="-1">Wireless Performance <a class="header-anchor" href="#wireless-performance" aria-label="Permalink to &quot;Wireless Performance&quot;">​</a></h3><ul><li><strong>Frequency Band:</strong> 2.4GHz</li><li><strong>Speed:</strong> Up to 11 Mbps (adjustable)</li><li><strong>Range:</strong> Up to 1000 meters (varies upon environments)</li><li><strong>Payload Capacity:</strong> Up to 1024 bytes</li></ul><h3 id="network-schemes" tabindex="-1">Network Schemes <a class="header-anchor" href="#network-schemes" aria-label="Permalink to &quot;Network Schemes&quot;">​</a></h3><ul><li><strong>Supported Topologies:</strong> 1:1, 1:N, N:N</li><li><strong>Collision Management:</strong> Time Slot-Based Response Delay</li></ul><h3 id="user-friendly-features" tabindex="-1">User-Friendly Features <a class="header-anchor" href="#user-friendly-features" aria-label="Permalink to &quot;User-Friendly Features&quot;">​</a></h3><ul><li><strong>Buttons:</strong> Pairing and Mode Switching</li><li><strong>LED Indicators:</strong> Real-time status updates</li><li><strong>Configuration:</strong> Web browser-based setup</li><li><strong>Micro USB Port for connecting to PC or GCS</strong></li></ul><h2 id="broadcast-communication" tabindex="-1">Broadcast Communication <a class="header-anchor" href="#broadcast-communication" aria-label="Permalink to &quot;Broadcast Communication&quot;">​</a></h2><p>With default settings enabled, the device automatically broadcasts data to all nearby J.Fi devices. Connect your external device or system to the <strong>Broadcast port</strong>. No additional setup is required.</p><p><img src="'+a+'" alt="J.Fi Wireless Telemetry Broadcast Communication"></p><h2 id="paired-communication" tabindex="-1">Paired Communication <a class="header-anchor" href="#paired-communication" aria-label="Permalink to &quot;Paired Communication&quot;">​</a></h2><ul><li>Modules must first undergo an initial pairing procedure.</li><li>Once paired, communication is <em>restricted to paired J.Fi devices</em>. Connect your external device or system to the <strong>Pair port.</strong></li></ul><p><img src="'+n+'" alt="J.Fi Wireless Telemetry Paired Communication"></p><h3 id="_1-1-pairing" tabindex="-1">1:1 Pairing <a class="header-anchor" href="#_1-1-pairing" aria-label="Permalink to &quot;1:1 Pairing&quot;">​</a></h3><p><img src="'+r+'" alt="J.Fi Wireless Telemetry Buttons"></p><ul><li>On <strong>each device,</strong> press and hold <em>button A</em>, then click the <em>RST button</em>. Release <em>button A</em> when <em>LED 1</em> blinks. <ul><li>Both devices will enter pairing mode</li></ul></li><li>Choose one module and double-click <em>button A</em></li><li>On the other module, click <em>button A</em> once</li><li>On the first module, click <em>button A</em> once again to finish pairing <ul><li>Pairing complete</li></ul></li></ul><h3 id="_1-n-pairing" tabindex="-1">1:N Pairing <a class="header-anchor" href="#_1-n-pairing" aria-label="Permalink to &quot;1:N Pairing&quot;">​</a></h3><ul><li>On <strong>each device,</strong> press and hold <em>button A</em>, then click the <em>RST button</em>. Release <em>button A</em> when <em>LED 1</em> blinks. <ul><li>All devices will enter pairing mode</li></ul></li><li><strong>Host module (1):</strong> Double-click <em>button A</em></li><li><strong>Client modules (N):</strong> Click <em>button A</em> once on each module to pair</li><li><strong>Host module (1):</strong> Click <em>button A</em> again to finish pairing <ul><li>Pairing complete.</li></ul></li></ul>',25),i("lite-youtube",{videoid:"CnjhTfvARmw",title:"J.Fi Wireless Telemetry Module Pairing Guide"},null,-1),e('<h2 id="px4-setup" tabindex="-1">PX4 Setup <a class="header-anchor" href="#px4-setup" aria-label="Permalink to &quot;PX4 Setup&quot;">​</a></h2><p>PX4 is plug-and-play with J.Fi if connected to the <code>TELEM1</code> port, and should connect without further connection.</p><p>If you want to use another port you will need to assign a MAVLink instance to the serial port (see <a href="./../peripherals/mavlink_peripherals.html">MAVLink Peripherals (GCS/OSD/Companion)</a>) (and possibly unassign whatever is currently using the port).</p><h3 id="one-to-one-1-1-setups" tabindex="-1">One-to-one (1:1) Setups <a class="header-anchor" href="#one-to-one-1-1-setups" aria-label="Permalink to &quot;One-to-one (1:1) Setups&quot;">​</a></h3><p>The <code>TELEM1</code> port is set to use <code>57600</code> as the baud rate by default (and J.Fi is set to match). This default baud rate is calibrated for inexpensive low-power telemetry radios. While this should be sufficient for 1:1 setups, J.Fi will work with much higher rates (i.e., <code>115200</code>).</p><p>If you want to change the baud rate:</p><ol><li>Change <a href="./../advanced_config/parameter_reference.html#SER_TEL1_BAUD">SER_TEL1_BAUD</a> if you&#39;re using the <code>TELEM1</code> port (see <a href="./../peripherals/serial_configuration.html">Serial Port Configuration</a> for other ports).</li><li>Update the baud rate in the <a href="#j-fi-configuration">J.Fi Configuration</a> to match.</li></ol><h3 id="one-to-many-1-n-setups" tabindex="-1">One-to-many (1:N) Setups <a class="header-anchor" href="#one-to-many-1-n-setups" aria-label="Permalink to &quot;One-to-many (1:N) Setups&quot;">​</a></h3><p>For one-to-many (1:N) setups a higher baud rate is <em>highly recommended</em> to ensure stable data reception. All J.Fi devices should be set to the same baud rate (although communication may work even when when devices use different baud rates). This should be changed in both PX4 and the J.Fi modules as explained in the previous section.</p><p>You will also need to make sure that all vehicles on the MAVLink network are assigned a unique <strong>System ID</strong> (<a href="./../advanced_config/parameter_reference.html#MAV_SYS_ID">MAV_SYS_ID</a>).</p><p><img src="'+l+'" alt="J.Fi Wireless Telemetry Broadcast Communication"></p>',11),i("lite-youtube",{videoid:"tPeJA2gn7Zw",title:"Simultaneous Control using J.Fi Wireless Telemetry Module"},null,-1),e('<h2 id="qgroundcontrol-configuration" tabindex="-1">QGroundControl Configuration <a class="header-anchor" href="#qgroundcontrol-configuration" aria-label="Permalink to &quot;QGroundControl Configuration&quot;">​</a></h2><p>The J.Fi will connect plug-and-play to <strong>QGroundControl</strong> and automatically connect just like a SiK Radio.</p><p>However if you change the baud rate from 57600 you will need to create and use a new link configuration:</p><ol><li>Disable SiK Radio in QGC (<strong>Application Settings → General → AutoConnect</strong>).</li><li>Create a new link configuration: <ul><li>Go to <strong>Application Settings → Comms Links</strong>.</li><li>Click <strong>Add</strong>.</li><li>Set <strong>Type</strong> to <strong>Serial</strong>, configure the <strong>Serial Port</strong> and <strong>Baud Rate</strong> to match the J.Fi device.</li></ul></li><li>Select <strong>Connect</strong> to connect with the new configuration.</li></ol><h2 id="j-fi-configuration" tabindex="-1">J.Fi Configuration <a class="header-anchor" href="#j-fi-configuration" aria-label="Permalink to &quot;J.Fi Configuration&quot;">​</a></h2><ul><li><strong>Device:</strong> Press and hold <em>button B</em>, then click the <em>RST button</em>. Release <em>button B</em> when <em>LED 2</em> blinks. <ul><li>Device enters configuration mode</li></ul></li><li><strong>Smart device:</strong> Connect to Wi-Fi network named <code>J.Fi-xxxxxx</code> (x: alphanumeric characters)</li><li><strong>Browser:</strong> Go to <code>192.168.4.1</code> to open the <strong>configuration page</strong>.</li><li><strong>Configuration page:</strong> Adjust settings as needed, then click <strong>Save</strong><ul><li><em>LED 2</em> blinks once upon saving</li></ul></li></ul><p><img src="'+s+'" alt="J.Fi Wireless Telemetry Broadcast Communication"></p><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="https://docs.google.com/document/d/1NaVwOLuMCuNpd0uxgilXZ_qfHAnsFgBmaPxX9WGY2h4/edit?usp=sharing" target="_blank" rel="noreferrer">User Manual</a></li><li><a href="https://github.com/SUV-Lab/J-Fi" target="_blank" rel="noreferrer">ROS Github</a></li></ul>',9)]))}const S=u(h,[["render",m]]);export{P as __pageData,S as default};
